def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        h, m = divmod(total, 60)
        hs = str(h)
        ms = str(m)
        if len(hs) == 1:
            hs = "0" + hs
        if len(ms) == 1:
            ms = "0" + ms
        return hs + ":" + ms

    def round_up_quarter(total):
        r = total % 15
        if r == 0:
            return total
        return total + (15 - r)

    people = [""]
    for name in attendees:
        people.append(name)

    requested = {}
    for day in days:
        requested[day] = True

    calendars = {}
    working_starts = []
    working_ends = []

    for person in people:
        data = api.read_calendar(person, "")
        daymap = {}
        for item in data["days"]:
            day = item["day"]
            if day in requested:
                daymap[day] = item
        calendars[person] = daymap

        wh = data["working_hours"].split("-")
        working_starts.append(to_minutes(wh[0]))
        working_ends.append(to_minutes(wh[1]))

    if len(working_starts) == 0:
        return {"starts": {}}

    base_start = max(working_starts)
    base_end = min(working_ends)

    if earliest != "":
        base_start = max(base_start, to_minutes(earliest))
    if latest_end != "":
        base_end = min(base_end, to_minutes(latest_end))

    result = {}

    for day in days:
        start = round_up_quarter(base_start)
        day_starts = []

        while start + minutes <= base_end:
            end = start + minutes
            free = True

            for person in people:
                day_entry = calendars[person].get(day)
                if day_entry != None:
                    for event in day_entry["events"]:
                        if event.get("show_as", "busy") != "free":
                            ev_start = to_minutes(event["start"])
                            ev_end = to_minutes(event["end"])
                            if ev_start < end and ev_end > start:
                                free = False
                                break
                    if not free:
                        break

            if free:
                day_starts.append(to_time(start))

            start += 15

        if len(day_starts) != 0:
            result[day] = day_starts

    return {"starts": result}
