def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parseTime(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def formatTime(value):
        h = value // 60
        m = value - h * 60
        hs = str(h)
        ms = str(m)
        if h < 10:
            hs = "0" + hs
        if m < 10:
            ms = "0" + ms
        return hs + ":" + ms

    def parseOffset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
            text = text[1:]
        elif text[0] == "+":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def ceilQuarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def clamp(value, low, high):
        if value < low:
            return low
        if value > high:
            return high
        return value

    def noteBuffer(note):
        low = note.lower()
        if "between any meeting with me" not in low:
            return 0
        if "minutes" not in low:
            return 0
        pos = low.find("minutes")
        digits = ""
        for i in range(pos - 1, -1, -1):
            ch = low[i]
            if ch.isdigit():
                digits = ch + digits
            else:
                if digits != "":
                    break
        if digits == "":
            return 0
        return int(digits)

    result = {}
    earliestVal = 0
    latestVal = 24 * 60
    if earliest != "":
        earliestVal = parseTime(earliest)
    if latest_end != "":
        latestVal = parseTime(latest_end)

    allPeople = [""] + attendees

    for day in days:
        userData = api.read_calendar("", day)
        userOffset = parseOffset(userData["utc_offset"])

        userWork = userData["working_hours"] if "working_hours" in userData else "00:00-23:59"
        userParts = userWork.split("-")
        userWorkStart = parseTime(userParts[0])
        userWorkEnd = parseTime(userParts[1])

        dayStart = 0
        dayEnd = 24 * 60
        windowStart = userWorkStart
        windowEnd = userWorkEnd

        busy = []

        for person in allPeople:
            data = userData if person == "" else api.read_calendar(person, day)

            personOffset = parseOffset(data["utc_offset"])
            work = data["working_hours"] if "working_hours" in data else "00:00-23:59"
            workParts = work.split("-")
            workStart = parseTime(workParts[0]) + (userOffset - personOffset)
            workEnd = parseTime(workParts[1]) + (userOffset - personOffset)

            workStart = clamp(workStart, dayStart, dayEnd)
            workEnd = clamp(workEnd, dayStart, dayEnd)

            if workStart > windowStart:
                windowStart = workStart
            if workEnd < windowEnd:
                windowEnd = workEnd

            buffer = 0
            if "note" in data:
                buffer = noteBuffer(data["note"])

            dayInfo = {}
            if "days" in data and len(data["days"]) > 0:
                wanted = day.lower()[:3]
                for item in data["days"]:
                    if "day" in item and item["day"].lower()[:3] == wanted:
                        dayInfo = item
                        break
                if dayInfo == {}:
                    dayInfo = data["days"][0]

            events = []
            if "events" in dayInfo:
                events = dayInfo["events"]

            for event in events:
                if "show_as" in event and event["show_as"] == "busy":
                    start = parseTime(event["start"]) + (userOffset - personOffset) - buffer
                    end = parseTime(event["end"]) + (userOffset - personOffset) + buffer
                    start = clamp(start, dayStart, dayEnd)
                    end = clamp(end, dayStart, dayEnd)
                    if start < end:
                        busy.append((start, end))

        if earliestVal > windowStart:
            windowStart = earliestVal
        if latestVal < windowEnd:
            windowEnd = latestVal

        windowStart = ceilQuarter(windowStart)
        latestStart = windowEnd - minutes

        starts = []
        if windowStart <= latestStart:
            t = windowStart
            while t <= latestStart:
                endT = t + minutes
                ok = True

                if t < earliestVal:
                    ok = False
                if endT > latestVal:
                    ok = False
                if t < userWorkStart or endT > userWorkEnd:
                    ok = False

                if ok:
                    for interval in busy:
                        if not (endT <= interval[0] or t >= interval[1]):
                            ok = False
                            break

                if ok:
                    starts.append(formatTime(t))

                t += 15

        if len(starts) > 0:
            result[day] = starts

    return {"starts": result}
