def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    weekdays = ["mon", "tue", "wed", "thu", "fri"]
    daypos = {}
    for i, d in enumerate(weekdays):
        daypos[d] = i

    def parseclock(text):
        if not text:
            return 0
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def formatclock(total):
        h, m = divmod(total, 60)
        hs = str(h)
        ms = str(m)
        if h < 10:
            hs = "0" + hs
        if m < 10:
            ms = "0" + ms
        return hs + ":" + ms

    def parseoffset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
            text = text[1:]
        elif text[0] == "+":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def ceilquarter(total):
        return ((total + 14) // 15) * 15

    def getcalendar(person):
        daysmap = {}
        offset = ""
        working = ""
        for d in weekdays:
            try:
                data = api.read_calendar(person, d)
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            if offset == "" and "utc_offset" in data:
                offset = data.get("utc_offset", "")
            if working == "" and "working_hours" in data:
                working = data.get("working_hours", "")
            if "days" in data and isinstance(data.get("days"), list):
                for item in data.get("days"):
                    if isinstance(item, dict):
                        dd = str(item.get("day", "")).lower()[:3]
                        if dd in daypos and dd not in daysmap:
                            daysmap[dd] = item
            elif "day" in data:
                dd = str(data.get("day", "")).lower()[:3]
                if dd in daypos and dd not in daysmap:
                    daysmap[dd] = data
        if offset == "":
            offset = "+00:00"
        if working == "":
            working = "00:00-24:00"
        return offset, working, daysmap

    def mergeintervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [list(intervals[0])]
        for a, b in intervals[1:]:
            last = merged[-1]
            if a <= last[1]:
                if b > last[1]:
                    last[1] = b
            else:
                merged.append([a, b])
        result = []
        for item in merged:
            result.append((item[0], item[1]))
        return result

    def buildblocked(offsettext, workingtext, daysmap):
        diff = parseoffset(offsettext) - baseoffset
        blocked = []
        if "-" in workingtext:
            parts = workingtext.split("-")
            if len(parts) == 2:
                wstart = parseclock(parts[0])
                wend = parseclock(parts[1])
                for d in weekdays:
                    if d in daysmap:
                        idx = daypos[d]
                        base = idx * 1440
                        if wstart > 0:
                            blocked.append((base - diff, base + wstart - diff))
                        if wend < 1440:
                            blocked.append((base + wend - diff, base + 1440 - diff))
        for d in weekdays:
            if d not in daysmap:
                continue
            item = daysmap[d]
            idx = daypos[d]
            base = idx * 1440
            events = item.get("events", [])
            if isinstance(events, list):
                for ev in events:
                    if not isinstance(ev, dict):
                        continue
                    show = ev.get("show_as", "busy")
                    if str(show).lower() == "free":
                        continue
                    start = ev.get("start", "")
                    end = ev.get("end", "")
                    if start and end:
                        a = base + parseclock(start) - diff
                        b = base + parseclock(end) - diff
                        blocked.append((a, b))
        return mergeintervals(blocked)

    wanted = {}
    for d in days:
        dd = str(d).lower()[:3]
        if dd in daypos:
            wanted[dd] = True

    if not wanted:
        return {"starts": {}}

    baseoffset, baseworking, basedays = getcalendar("")
    baseoffset = parseoffset(baseoffset)

    allblocked = []

    userblocked = buildblocked("+00:00", baseworking, basedays)
    for item in userblocked:
        allblocked.append(item)

    for person in attendees:
        offsettext, workingtext, daysmap = getcalendar(person)
        blocked = buildblocked(offsettext, workingtext, daysmap)
        for item in blocked:
            allblocked.append(item)

    allblocked = mergeintervals(allblocked)

    early = 0
    if earliest:
        early = ceilquarter(parseclock(earliest))
    else:
        early = 0

    late = 1440 - int(minutes)
    if latest_end:
        late = parseclock(latest_end) - int(minutes)

    if early < 0:
        early = 0
    if late > 1440 - int(minutes):
        late = 1440 - int(minutes)

    if late < early:
        return {"starts": {}}

    starts = {}
    for d in weekdays:
        if d not in wanted:
            continue
        idx = daypos[d]
        daybase = idx * 1440
        found = []
        t = early
        while t <= late and t < 1440:
            startabs = daybase + t
            endabs = startabs + int(minutes)
            free = True
            for a, b in allblocked:
                if a >= endabs:
                    break
                if b > startabs and a < endabs:
                    free = False
                    break
            if free:
                found.append(formatclock(t))
            t += 15
        if found:
            starts[d] = found

    return {"starts": starts}
