def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def format_time(total):
        h, m = divmod(int(total), 60)
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def ceil_quarter(total):
        q, r = divmod(int(total), 15)
        if r != 0:
            q = q + 1
        return q * 15

    def normalize_day(day):
        d = day.lower()
        if d.startswith("mon"):
            return "mon"
        if d.startswith("tue"):
            return "tue"
        if d.startswith("wed"):
            return "wed"
        if d.startswith("thu"):
            return "thu"
        if d.startswith("fri"):
            return "fri"
        return d[0:3]

    def clip_interval(start, end):
        if end <= 0 or start >= 1440:
            return None
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if end <= start:
            return None
        return (start, end)

    result = {"starts": {}}
    if len(days) == 0:
        return result

    earliest_min = 0
    if earliest != "":
        earliest_min = parse_time(earliest)

    latest_min = 1440
    if latest_end != "":
        latest_min = parse_time(latest_end)

    if earliest_min < 0:
        earliest_min = 0
    if latest_min > 1440:
        latest_min = 1440

    first_start = ceil_quarter(earliest_min)
    last_start_limit = latest_min - minutes
    if last_start_limit > 1440 - minutes:
        last_start_limit = 1440 - minutes

    for day in days:
        user_resp = api.read_calendar("", day)
        if not isinstance(user_resp, dict):
            continue

        user_offset = parse_offset(user_resp.get("utc_offset", ""))

        user_day_key = normalize_day(day)
        day_blocks = user_resp.get("days", [])
        if isinstance(day_blocks, list) and len(day_blocks) > 0 and isinstance(day_blocks[0], dict):
            if day_blocks[0].get("day", "") != "":
                user_day_key = day_blocks[0].get("day", user_day_key)

        calendars = [("", user_resp)]
        for person in attendees:
            calendars.append((person, api.read_calendar(person, day)))

        working_ranges = []
        busy_ranges = []

        for person, resp in calendars:
            if not isinstance(resp, dict):
                working_ranges = []
                busy_ranges = []
                break

            person_offset = parse_offset(resp.get("utc_offset", ""))
            shift = user_offset - person_offset

            wh = resp.get("working_hours", "")
            if wh != "" and len(wh) >= 11:
                ws = parse_time(wh[0:5]) + shift
                we = parse_time(wh[6:11]) + shift
                clipped = clip_interval(ws, we)
                if clipped is None:
                    working_ranges = []
                    busy_ranges = []
                    break
                working_ranges.append(clipped)

            person_days = resp.get("days", [])
            if isinstance(person_days, list) and len(person_days) > 0 and isinstance(person_days[0], dict):
                events = person_days[0].get("events", [])
                if isinstance(events, list):
                    for event in events:
                        if not isinstance(event, dict):
                            continue
                        if event.get("show_as", "busy") == "free":
                            continue
                        start_text = event.get("start", "")
                        end_text = event.get("end", "")
                        if start_text == "" or end_text == "":
                            continue
                        bs = parse_time(start_text) + shift
                        be = parse_time(end_text) + shift
                        clipped_busy = clip_interval(bs, be)
                        if clipped_busy is not None:
                            busy_ranges.append(clipped_busy)

        if len(working_ranges) == 0:
            continue

        starts = []
        if last_start_limit >= first_start:
            for start in range(first_start, last_start_limit + 1, 15):
                end = start + minutes
                if end > latest_min or end > 1440:
                    continue

                allowed = True
                for ws, we in working_ranges:
                    if start < ws or end > we:
                        allowed = False
                        break
                if not allowed:
                    continue

                for bs, be in busy_ranges:
                    if start < be and end > bs:
                        allowed = False
                        break
                if allowed:
                    starts.append(format_time(start))

        if len(starts) > 0:
            result["starts"][user_day_key] = starts

    return result
