def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def toMin(text):
        return int(text[:2]) * 60 + int(text[3:5])

    def toClock(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def offsetMin(text):
        sign = -1 if text[0] == "-" else 1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def parseWindow(text):
        parts = text.split("-")
        return toMin(parts[0]), toMin(parts[1])

    def getDay(cal, wanted):
        items = cal.get("days", [])
        if len(items) == 0:
            return None
        short = wanted[:3].lower()
        full = wanted.lower()
        for item in items:
            dayname = item.get("day", "").lower()
            if dayname == short or dayname == full:
                return item
        return items[0]

    earliestMin = 0 if earliest == "" else toMin(earliest)
    latestMin = 24 * 60 if latest_end == "" else toMin(latest_end)

    starts = {}

    for day in days:
        userCal = api.read_calendar("", day)
        userDay = getDay(userCal, day)
        if userDay is None:
            continue

        userOffset = offsetMin(userCal.get("utc_offset", "+00:00"))
        workStart, workEnd = parseWindow(userCal.get("working_hours", "00:00-24:00"))
        commonStart = workStart
        commonEnd = workEnd
