        mm = str(m)
        if h < 10:
            hh = "0" + hh
        if m < 10:
            mm = "0" + mm
        return hh + ":" + mm

    def get_day_info(cal):
        day_list = cal.get("days", [])
        if len(day_list) == 0:
            return {}
        return day_list[0]

    def calendar_availability(cal, delta):
        work = [False] * 1440
        wh = cal.get("working_hours", "")
        if wh:
            parts = wh.split("-")
            if len(parts) == 2:
                s = parse_time(parts[0]) + delta
                e = parse_time(parts[1]) + delta
                if s < 0:
                    s = 0
                if e > 1440:
                    e = 1440
                if s < e:
                    for i in range(s, e):
                        work[i] = True

        avail = work[:]
        note = cal.get("note", "")
        buffer_minutes = 0
        low = note.lower()
        if "leave" in low and "minute" in low:
            buffer_minutes = parse_buffer(low)

        day_info = get_day_info(cal)
        events = day_info.get("events", [])
        for ev in events:
            s = parse_time(ev.get("start", "")) + delta
            e = parse_time(ev.get("end", "")) + delta
            if s < 0:
                s = 0
            if e > 1440:
                e = 1440
            if s >= e:
                continue

            show = ev.get("show_as", "busy")
            if show == "free":
                for i in range(s, e):
                    if work[i]:
                        avail[i] = True
            else:
                s2 = s - buffer_minutes
                e2 = e + buffer_minutes
                if s2 < 0:
                    s2 = 0
                if e2 > 1440:
                    e2 = 1440
                if s2 < e2:
                    for i in range(s2, e2):
                        avail[i] = False

        return avail

    result = {"starts": {}}
    earliest_min = 0
    if earliest:
        earliest_min = parse_time(earliest)
    latest_min = 1440
    if latest_end:
        latest_min = parse_time(latest_end)

    for day in days:
        user_cal = api.read_calendar("", day)
        user_offset = parse_offset(user_cal.get("utc_offset", "+00:00"))
        combined = calendar_availability(user_cal, 0)

        for person in attendees:
            other_cal = api.read_calendar(person, day)
            other_offset = parse_offset(other_cal.get("utc_offset", "+00:00"))
            delta = user_offset - other_offset
            other_avail = calendar_availability(other_cal, delta)
            for i in range(1440):
                if not other_avail[i]:
                    combined[i] = False

        starts = []
        for start in range(0, 1440, 15):
            if start < earliest_min:
                continue
            end = start + minutes
            if end > latest_min:
                continue
            if end > 1440:
                continue
            good = True
            for i in range(start, end):
                if not combined[i]:
                    good = False
                    break
            if good:
                starts.append(format_time(start))

        if len(starts) > 0:
            result["starts"][day] = starts

    return result
