def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    day_to_index = {"mon": 0, "tue": 1, "wed": 2, "thu": 3, "fri": 4}
    index_to_day = ["mon", "tue", "wed", "thu", "fri"]

    def time_to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        hour = total // 60
        minute = total % 60
        hour_text = str(hour)
        minute_text = str(minute)
        if hour < 10:
            hour_text = "0" + hour_text
        if minute < 10:
            minute_text = "0" + minute_text
        return hour_text + ":" + minute_text

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        parts = text[1:].split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def shift_day(day, shift):
        base = day_to_index.get(day, -1)
        if base < 0:
            return ""
        new_index = base + shift
        if new_index < 0 or new_index >= len(index_to_day):
            return ""
        return index_to_day[new_index]

    def convert_interval(day, start_min, end_min, delta):
        pieces = []
        start_total = start_min + delta
        end_total = end_min + delta
        start_shift, start_local = divmod(start_total, 1440)
        end_shift, end_local = divmod(end_total, 1440)

        if start_shift == end_shift:
            target_day = shift_day(day, start_shift)
            if target_day != "" and start_local < end_local:
                pieces.append((target_day, start_local, end_local))
            return pieces

        first_day = shift_day(day, start_shift)
        if first_day != "" and start_local < 1440:
            pieces.append((first_day, start_local, 1440))

        shift = start_shift + 1
        while shift < end_shift:
            middle_day = shift_day(day, shift)
            if middle_day != "":
                pieces.append((middle_day, 0, 1440))
            shift += 1

        last_day = shift_day(day, end_shift)
        if last_day != "" and end_local > 0:
            pieces.append((last_day, 0, end_local))

        return pieces

    def add_segments(target, segments):
        for item in segments:
            day = item[0]
            if day in target:
                target[day].append((item[1], item[2]))

    def within_any(start_min, end_min, segments):
        for segment in segments:
            if start_min >= segment[0] and end_min <= segment[1]:
                return True
        return False

    def overlaps_any(start_min, end_min, segments):
        for segment in segments:
            if start_min < segment[1] and end_min > segment[0]:
                return True
        return False

    people = [""]
    for name in attendees:
        if name not in people:
            people.append(name)

    calendars = {}
    for person in people:
        calendars[person] = api.read_calendar(person, "")

    user_offset = parse_offset(calendars[""]["utc_offset"])

    person_data = {}
    for person in people:
        cal = calendars[person]
        delta = user_offset - parse_offset(cal["utc_offset"])

        work_map = {}
        busy_map = {}
        for day in days:
            key = day.lower()
            if key in day_to_index:
                work_map[key] = []
                busy_map[key] = []

        work_text = cal["working_hours"]
        work_start = time_to_minutes(work_text.split("-")[0])
        work_end = time_to_minutes(work_text.split("-")[1])

        for entry in cal.get("days", []):
            local_day = entry.get("day", "")
            if local_day not in day_to_index:
                continue

            work_segments = convert_interval(local_day, work_start, work_end, delta)
            add_segments(work_map, work_segments)

            for event in entry.get("events", []):
                if event.get("show_as") == "busy":
                    event_start = time_to_minutes(event["start"])
                    event_end = time_to_minutes(event["end"])
                    busy_segments = convert_interval(local_day, event_start, event_end, delta)
                    add_segments(busy_map, busy_segments)

        person_data[person] = {"work": work_map, "busy": busy_map}

    start_floor = 0
    if earliest != "":
        start_floor = time_to_minutes(earliest)

    end_cap = 1440
    if latest_end != "":
        end_cap = time_to_minutes(latest_end)

    latest_start = end_cap - minutes
    if latest_end == "":
        latest_start = 1440 - minutes

    first_start = start_floor
    remainder = first_start % 15
    if remainder != 0:
        first_start += 15 - remainder

    result = {}
    for day in days:
        key = day.lower()
        if key not in day_to_index:
            continue

        starts = []
        current = first_start
        while current <= latest_start:
            end_time = current + minutes
            if end_time <= 1440:
                ok = True
                for person in people:
                    work_segments = person_data[person]["work"].get(key, [])
                    busy_segments = person_data[person]["busy"].get(key, [])
                    if not within_any(current, end_time, work_segments):
                        ok = False
                        break
                    if overlaps_any(current, end_time, busy_segments):
                        ok = False
                        break
                if ok:
                    starts.append(format_time(current))
            current += 15

        if starts:
            result[key] = starts

    return {"starts": result}
