def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def toMinutes(t):
        return int(t[:2]) * 60 + int(t[3:5])

    def fromMinutes(m):
        h = m // 60
        n = m % 60
        if h < 10:
            hs = "0" + str(h)
        else:
            hs = str(h)
        if n < 10:
            ns = "0" + str(n)
        else:
            ns = str(n)
        return hs + ":" + ns

    def parseOffset(s):
        if not s:
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
        return sign * (int(s[1:3]) * 60 + int(s[4:6]))

    def ceilQuarter(m):
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def makeBusy(cal, userOff):
        busy = [True] * 1440
        if not isinstance(cal, dict):
            return busy

        off = parseOffset(cal.get("utc_offset", ""))
        delta = userOff - off

        wh = cal.get("working_hours", "")
        if isinstance(wh, str) and len(wh) >= 11 and "-" in wh:
            ws = toMinutes(wh[:5]) + delta
            we = toMinutes(wh[6:11]) + delta
        else:
            ws = 0
            we = 1440

        a = ws
        if a < 0:
            a = 0
        b = we
        if b > 1440:
            b = 1440
        i = a
        while i < b:
            if 0 <= i < 1440:
                busy[i] = False
            i += 1

        for entry in cal.get("days", []):
            if not isinstance(entry, dict):
                continue
            for ev in entry.get("events", []):
                if not isinstance(ev, dict):
                    continue
                if ev.get("show_as", "busy") == "free":
                    continue
                s = toMinutes(ev.get("start", "00:00")) + delta
                e = toMinutes(ev.get("end", "00:00")) + delta
                a = s
                if a < 0:
                    a = 0
                b = e
                if b > 1440:
                    b = 1440
                i = a
                while i < b:
                    if 0 <= i < 1440:
                        busy[i] = True
                    i += 1

        return busy

    result = {}
    meetingLen = int(minutes)

    if earliest == "":
        earliestStart = 0
    else:
        earliestStart = toMinutes(earliest)
    earliestStart = ceilQuarter(earliestStart)

    if latest_end == "":
        latestEnd = 1440
    else:
        latestEnd = toMinutes(latest_end)

    lastStart = latestEnd - meetingLen
    maxByDay = 1440 - meetingLen
    if maxByDay < lastStart:
        lastStart = maxByDay

    for day in days:
        userCal = api.read_calendar("", day)
        userOff = 0
        if isinstance(userCal, dict):
            userOff = parseOffset(userCal.get("utc_offset", ""))

        dayKey = day
        if isinstance(userCal, dict):
            userDays = userCal.get("days", [])
            if len(userDays) > 0 and isinstance(userDays[0], dict) and "day" in userDays[0]:
                dayKey = userDays[0]["day"]

        combinedBusy = [False] * 1440

        busy = makeBusy(userCal, userOff)
        i = 0
        while i < 1440:
            if busy[i]:
                combinedBusy[i] = True
            i += 1

        for person in attendees:
            cal = api.read_calendar(person, day)
            busy = makeBusy(cal, userOff)
            i = 0
            while i < 1440:
                if busy[i]:
                    combinedBusy[i] = True
                i += 1

        starts = []
        s = earliestStart
        if s < 0:
            s = 0
        if s % 15 != 0:
            s = ceilQuarter(s)

        if s <= lastStart:
            while s <= lastStart:
                e = s + meetingLen
                ok = True
                m = s
                while m < e:
                    if combinedBusy[m]:
                        ok = False
                        break
                    m += 1
                if ok:
                    starts.append(fromMinutes(s))
                s += 15

        if len(starts) > 0:
            result[dayKey] = starts

    return {"starts": result}
