    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(value):
        hour = value // 60
        minute = value % 60
        text = ""
        if hour < 10:
            text += "0"
        text += str(hour)
        text += ":"
        if minute < 10:
            text += "0"
        text += str(minute)
        return text

    def next_quarter(value):
        remainder = value % 15
        if remainder == 0:
            return value
        return value + (15 - remainder)

    def parse_buffer(note):
        if note == "":
            return 0
        digits = ""
        started = False
        for ch in note:
            if ch >= "0" and ch <= "9":
                digits += ch
                started = True
            elif started:
                break
        if digits == "":
            return 0
        return int(digits)

    people = [""]
    for name in attendees:
        found = False
        for person in people:
            if person == name:
                found = True
                break
        if not found:
            people.append(name)

    result = {}

    for day in days:
        calendars = []
        for person in people:
            data = api.read_calendar(person, day)
            work_hours = data.get("working_hours", "00:00-24:00")
            work_parts = work_hours.split("-")
            work_start = to_minutes(work_parts[0])
            work_end = to_minutes(work_parts[1])

            buffer_minutes = parse_buffer(data.get("note", ""))
            entries = data.get("days", [])
            events = []
            if len(entries) > 0:
                events = entries[0].get("events", [])

            blocked = []
            for event in events:
                if event.get("show_as", "busy") != "free":
                    start = to_minutes(event["start"])
                    end = to_minutes(event["end"])
                    if buffer_minutes > 0:
                        start -= buffer_minutes
                        end += buffer_minutes
                    if start < 0:
                        start = 0
                    if end > 24 * 60:
                        end = 24 * 60
                    blocked.append((start, end))

            calendars.append((work_start, work_end, blocked))

        if len(calendars) == 0:
            continue

        if earliest == "":
            start_limit = 0
        else:
            start_limit = to_minutes(earliest)

        common_start = start_limit
        for cal in calendars:
            if cal[0] > common_start:
                common_start = cal[0]

        common_end = None
        for cal in calendars:
            if common_end is None or cal[1] < common_end:
                common_end = cal[1]

        if latest_end != "":
            latest_limit = to_minutes(latest_end)
            if latest_limit < common_end:
                common_end = latest_limit

        start = next_quarter(common_start)
        day_starts = []

        while start + minutes <= common_end:
            ok = True
            for cal in calendars:
                work_start = cal[0]
                work_end = cal[1]
                if start < work_start or start + minutes > work_end:
                    ok = False
                    break
                for block in cal[2]:
                    if not (start + minutes <= block[0] or start >= block[1]):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                day_starts.append(to_time(start))
            start += 15

        if len(day_starts) > 0:
            result[day] = day_starts

    return {"starts": result}
