        sign = 1
        if text[:1] == "-":
            sign = -1
        hour = int(text[1:3])
        minute = int(text[4:6])
        return sign * (hour * 60 + minute)

    def day_info(response):
        days_list = response["days"]
        if len(days_list) == 0:
            return None
        return days_list[0]

    earliest_min = parse_time(earliest) if earliest != "" else 0
    latest_min = parse_time(latest_end) if latest_end != "" else 24 * 60

