            info = user_day if person == "" else day_info(response)
            if info is None:
                ok = False
                break

            shift = parse_offset(response["utc_offset"]) - user_offset
            working_start_text, working_end_text = response["working_hours"].split("-")
            working_start = parse_time(working_start_text)
            working_end = parse_time(working_end_text)

            busy = []
            for event in info["events"]:
                if event.get("show_as", "") != "free":
                    busy.append((parse_time(event["start"]), parse_time(event["end"])))

            people.append((shift, working_start, working_end, busy))

        if not ok:
            continue

        starts = []
        for start in range(0, 24 * 60, 15):
            end = start + minutes
            if start < earliest_min:
                continue
            if end > latest_min:
                continue

            free = True
            for shift, working_start, working_end, busy in people:
                local_start = start + shift
                local_end = end + shift

                if local_start < working_start or local_end > working_end:
                    free = False
                    break

                for busy_start, busy_end in busy:
                    if local_start < busy_end and local_end > busy_start:
                        free = False
                        break

                if not free:
                    break

            if free:
                starts.append(format_time(start))

        if len(starts) > 0:
            result["starts"][user_day["day"]] = starts

    return result
