def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        s = str(text).strip()
        parts = s.split(":")
        if len(parts) == 2:
            return int(parts[0]) * 60 + int(parts[1])
        if len(s) <= 2:
            return int(s) * 60
        return int(s[0:len(s) - 2]) * 60 + int(s[len(s) - 2:])

    def parse_offset(text):
        if text == None:
            return 0
        if isinstance(text, int):
            return text
        if isinstance(text, float):
            return int(text)
        s = str(text).strip()
        if s == "":
            return 0
        sign = 1
        if s[0] == "-":
            sign = -1
            s = s[1:]
        elif s[0] == "+":
            s = s[1:]
        parts = s.split(":")
        if len(parts) == 2:
            return sign * (int(parts[0]) * 60 + int(parts[1]))
        if len(s) <= 2:
            return sign * (int(s) * 60)
        return sign * (int(s[0:len(s) - 2]) * 60 + int(s[len(s) - 2:]))

    def to_time(total):
        total = total % 1440
        h, m = divmod(total, 60)
        hs = str(h)
        ms = str(m)
        if len(hs) == 1:
            hs = "0" + hs
        if len(ms) == 1:
            ms = "0" + ms
        return hs + ":" + ms

    def round_up_quarter(total):
        r = total % 15
        if r == 0:
            return total
        return total + (15 - r)

    def split_interval(start, end):
        pieces = []
        if start < end:
            pieces.append((start, end))
        elif start > end:
            pieces.append((start, 1440))
            pieces.append((0, end))
        return pieces

    def normalize_interval(start_text, end_text, delta):
        raw_start = parse_time(start_text)
        raw_end = parse_time(end_text)

        if raw_end == raw_start:
            return []

        if raw_end <= raw_start:
            raw_end += 1440

        if raw_end - raw_start >= 1440:
            return [(0, 1440)]

        start = (raw_start + delta) % 1440
        end = (raw_end + delta) % 1440
        return split_interval(start, end)

    def within(intervals, start, end):
        for s, e in intervals:
            if start >= s and end <= e:
                return True
        return False

    def overlaps(intervals, start, end):
        for s, e in intervals:
            if s < end and e > start:
                return True
        return False

    requested = {}
    daylist = []
    for day in days:
        if day not in requested:
            requested[day] = True
            daylist.append(day)

    people = [""]
    for name in attendees:
        if name not in people:
            people.append(name)

    user_offset = 0
    data_by_person = {}

    for person in people:
        data = api.read_calendar(person, "")
        data_by_person[person] = data
        if person == "":
            user_offset = parse_offset(data.get("utc_offset", "00:00"))

    work_by_person = {}
    busy_by_person_day = {}

    for person in people:
        data = data_by_person[person]
        offset = parse_offset(data.get("utc_offset", "00:00"))
        delta = user_offset - offset

        wh = data.get("working_hours", "00:00-24:00")
        parts = wh.split("-")
        work_by_person[person] = normalize_interval(parts[0], parts[1], delta)

        daymap = {}
        for item in data.get("days", []):
            day = item.get("day")
            if day in requested:
                intervals = []
                for event in item.get("events", []):
                    if event.get("show_as", "busy") != "free":
                        pieces = normalize_interval(event["start"], event["end"], delta)
                        for piece in pieces:
                            intervals.append(piece)
                daymap[day] = intervals
        busy_by_person_day[person] = daymap

    result = {}
    if minutes <= 0:
        return {"starts": result}

    search_start = 0
    if earliest != "":
        search_start = parse_time(earliest)
    search_end = 1440
    if latest_end != "":
        search_end = parse_time(latest_end)

    if search_start < 0:
        search_start = 0
    if search_end > 1440:
        search_end = 1440

    start = round_up_quarter(search_start)
    while start + minutes <= search_end:
        end = start + minutes
        for day in daylist:
            ok = True
            for person in people:
                if not within(work_by_person[person], start, end):
                    ok = False
                    break
                if overlaps(busy_by_person_day[person].get(day, []), start, end):
                    ok = False
                    break
            if ok:
                if day not in result:
                    result[day] = []
                result[day].append(to_time(start))
        start += 15

    return {"starts": result}
