        event_before, event_after = buffer_pair(event)
        before = default_before
        after = default_after
        if event_before > before:
            before = event_before
        if event_after > after:
            after = event_after
        abs_start = day_idx * 1440 + start + delta - before
        abs_end = day_idx * 1440 + end + delta + after
        pieces = split_abs_interval(abs_start, abs_end)
        for piece in pieces:
            store.append(piece)

    requested = []
    requested_index_seen = []
    for day in days:
        idx = day_index(day)
        if idx >= 0 and idx not in requested_index_seen:
            requested_index_seen.append(idx)
            requested.append((str(day), idx))

    if minutes <= 0 or len(requested) == 0:
        return {"starts": {}}

    people = [""]
    for name in attendees:
        if name not in people:
            people.append(name)

    user_data = api.read_calendar("", "")
    if not isinstance(user_data, dict):
        user_data = {}
    user_offset = parse_offset(user_data.get("utc_offset", "00:00"))

    work_by_person = {}
    busy_by_person = {}

    for person in people:
        data = api.read_calendar(person, "")
        if not isinstance(data, dict):
            data = {}
        offset = parse_offset(data.get("utc_offset", "00:00"))
        delta = user_offset - offset

        global_work = data.get("working_hours", "00:00-24:00")
        person_before, person_after = buffer_pair(data)

        work_intervals = []
        busy_intervals = []

        raw_days = data.get("days", [])
        day_items = []
        if isinstance(raw_days, dict):
            for key in raw_days:
                value = raw_days.get(key)
                if isinstance(value, dict):
                    item = {}
                    for k in value:
                        item[k] = value.get(k)
                    if "day" not in item:
                        item["day"] = key
                    day_items.append(item)
                else:
                    item = {"day": key}
                    if isinstance(value, list) or isinstance(value, tuple):
                        item["events"] = value
                    day_items.append(item)
        elif isinstance(raw_days, list):
            day_items = raw_days

        explicit_day_indices = []

        for item in day_items:
            if not isinstance(item, dict):
                continue
            day_name = item.get("day")
            idx = day_index(day_name)
            if idx < 0:
                continue
            if idx not in explicit_day_indices:
                explicit_day_indices.append(idx)

            day_work = item.get("working_hours", global_work)
            add_work_interval(work_intervals, idx, day_work, delta)

            item_before, item_after = buffer_pair(item)
            events = item.get("events", [])
            if isinstance(events, dict):
                event_list = []
                for k in events:
                    event_list.append(events.get(k))
            elif isinstance(events, list) or isinstance(events, tuple):
                event_list = events
            else:
                event_list = []

            for event in event_list:
                if not isinstance(event, dict):
                    continue
                before = person_before
                after = person_after
                if item_before > before:
                    before = item_before
                if item_after > after:
                    after = item_after
                add_busy_interval(busy_intervals, idx, event, delta, before, after)

        for day_name, idx in requested:
            if idx not in explicit_day_indices:
                add_work_interval(work_intervals, idx, global_work, delta)

        work_by_person[person] = work_intervals
        busy_by_person[person] = busy_intervals

    result = {}
    search_start = 0
    if earliest != "":
        search_start = parse_time(earliest)
    search_end = 1440
    if latest_end != "":
        search_end = parse_time(latest_end)

    if search_start < 0:
        search_start = 0
    if search_end < 0:
        search_end = 0
    if search_end > 1440:
        search_end = 1440

    start_min = round_up_quarter(search_start)
    if start_min < 0:
        start_min = 0

    for day_name, day_idx in requested:
        starts = []
        current = start_min
        while current + minutes <= search_end:
            candidate_start = day_idx * 1440 + current
            candidate_end = candidate_start + minutes
            ok = True
            for person in people:
                if not within_any(work_by_person.get(person, []), candidate_start, candidate_end):
                    ok = False
                    break
                if overlaps_any(busy_by_person.get(person, []), candidate_start, candidate_end):
                    ok = False
                    break
            if ok:
                starts.append(to_time(current))
            current += 15
        if len(starts) > 0:
            result[day_name] = starts

    return {"starts": result}
