def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def daykey(text):
        text = text.strip().lower()
        return text[:3]

    def timemin(text):
        parts = text.split(":")
        hour = int(parts[0])
        minute = int(parts[1])
        if hour == 24 and minute == 0:
            return 1440
        return hour * 60 + minute

    def offmin(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        hour = int(text[1:3])
        minute = int(text[4:6])
        return sign * (hour * 60 + minute)

    def fmt(mins):
        return str(mins // 60).zfill(2) + ":" + str(mins % 60).zfill(2)

    def clip(start, end, shift, buffer):
        a = start + shift - buffer
        b = end + shift + buffer
        if b <= 0 or a >= 1440:
            return []
        if a < 0:
            a = 0
        if b > 1440:
            b = 1440
        if a < b:
            return [(a, b)]
        return []

    def contains(start, end, segments):
        for a, b in segments:
            if start >= a and end <= b:
                return True
        return False

    def overlap(start, end, segments):
        for a, b in segments:
            if start < b and a < end:
                return True
        return False

    def ceilquarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def floorquarter(value):
        return value - (value % 15)

    def unique(names):
        out = []
        seen = set()
        for name in names:
            if name and name not in seen:
                seen.add(name)
                out.append(name)
        return out

    usercal = api.read_calendar("", "")
    useroff = offmin(usercal["utc_offset"])
    userparts = usercal["working_hours"].split("-")
    userworkstart = timemin(userparts[0])
    userworkend = timemin(userparts[1])

    userdays = dict()
    for entry in usercal.get("days", []):
        k = daykey(entry.get("day", ""))
        if k:
            userdays[k] = entry

    people = []
    people.append({
        "off": useroff,
        "workstart": userworkstart,
        "workend": userworkend,
        "buffer": 0,
        "days": userdays,
    })

    for name in unique(attendees):
        cal = api.read_calendar(name, "")
        off = offmin(cal["utc_offset"])
        parts = cal["working_hours"].split("-")
        ws = timemin(parts[0])
        we = timemin(parts[1])
        daymap = dict()
        for entry in cal.get("days", []):
            k = daykey(entry.get("day", ""))
            if k:
                daymap[k] = entry
        note = cal.get("note", "")
        buffer = 15 if isinstance(note, str) and "15 minutes" in note else 0
        people.append({
            "off": off,
            "workstart": ws,
            "workend": we,
            "buffer": buffer,
            "days": daymap,
        })

    requested = []
    seen_days = set()
    for d in days:
        k = daykey(d)
        if k and k not in seen_days:
            seen_days.add(k)
            requested.append(k)

    lower = 0
    if earliest != "":
        lower = ceilquarter(timemin(earliest))

    upper = 1440 - minutes
    if latest_end != "":
        upper = timemin(latest_end) - minutes
    if upper > 1440 - minutes:
        upper = 1440 - minutes
    upper = floorquarter(upper)

    result = dict()

    for day in requested:
        if lower > upper:
            continue

        daychecks = []
        skipday = False

        for person in people:
            delta = useroff - person["off"]
            worksegs = clip(person["workstart"], person["workend"], delta, 0)
            if not worksegs:
                skipday = True
                break

            busysegs = []
            dayentry = person["days"].get(day)
            if dayentry is not None:
                for event in dayentry.get("events", []):
                    if event.get("show_as") == "busy":
                        start = timemin(event["start"])
                        end = timemin(event["end"])
                        for seg in clip(start, end, delta, person["buffer"]):
                            busysegs.append(seg)

            daychecks.append((worksegs, busysegs))

        if skipday:
            continue

        starts = []
        start = lower
        while start <= upper:
            end = start + minutes
            ok = True
            for worksegs, busysegs in daychecks:
                if not contains(start, end, worksegs) or overlap(start, end, busysegs):
                    ok = False
                    break
            if ok:
                starts.append(fmt(start))
            start += 15

        if starts:
            result[day] = starts

    return {"starts": result}
