def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def normalize_day(day):
        t = str(day).lower()
        if t.startswith("mon"):
            return "mon"
        if t.startswith("tue"):
            return "tue"
        if t.startswith("wed"):
            return "wed"
        if t.startswith("thu"):
            return "thu"
        if t.startswith("fri"):
            return "fri"
        return t[:3]

    def parse_time(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def format_time(total):
        h = total // 60
        m = total % 60
        return ("0" + str(h))[-2:] + ":" + ("0" + str(m))[-2:]

    def parse_offset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def ceil_quarter(total):
        return ((total + 14) // 15) * 15

    def merge(intervals):
        items = sorted(intervals)
        merged = []
        for s, e in items:
            if e <= s:
                continue
            if not merged:
                merged.append([s, e])
            else:
                last = merged[len(merged) - 1]
                if s > last[1]:
                    merged.append([s, e])
                elif e > last[1]:
                    last[1] = e
        return merged

    def day_map(calendar):
        result = {}
        for item in calendar.get("days", []):
            result[normalize_day(item.get("day", ""))] = item
        return result

    def interval_shift(start_text, end_text, delta):
        return parse_time(start_text) + delta, parse_time(end_text) + delta

    def get_work_hours(calendar):
        text = calendar.get("working_hours", "00:00-24:00")
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    user_calendar = api.read_calendar("", "")
    user_offset = parse_offset(user_calendar.get("utc_offset", "-00:00"))
    user_days = day_map(user_calendar)
    user_work_start, user_work_end = get_work_hours(user_calendar)

    seen = set()
    people = []
    for name in attendees:
        if name not in seen:
            seen.add(name)
            people.append(name)

    calendars = {}
    for person in people:
        calendars[person] = api.read_calendar(person, "")

    earliest_minutes = -1
    if earliest != "":
        earliest_minutes = parse_time(earliest)
    latest_minutes = -1
    if latest_end != "":
        latest_minutes = parse_time(latest_end)

    starts = {}
    for day in days:
        day_key = normalize_day(day)
        user_day = user_days.get(day_key)
        if not user_day:
            continue

        common_start = user_work_start
        common_end = user_work_end
        busy = []

        s, e = get_work_hours(user_calendar)
        common_start = max(common_start, s)
        common_end = min(common_end, e)

        user_busy_events = user_day.get("events", [])
        for event in user_busy_events:
            if event.get("show_as") == "busy":
                s = parse_time(event.get("start", "00:00"))
                e = parse_time(event.get("end", "00:00"))
                if e > s:
                    busy.append([s, e])

        for person in people:
            calendar = calendars.get(person)
            if not calendar:
                continue
            offset = parse_offset(calendar.get("utc_offset", "-00:00"))
            delta = user_offset - offset
            person_day = day_map(calendar).get(day_key)
            if not person_day:
                continue

            ps, pe = get_work_hours(calendar)
            ps = ps + delta
            pe = pe + delta
            if ps > common_start:
                common_start = ps
            if pe < common_end:
                common_end = pe

            note = str(calendar.get("note", "")).lower()
            buffer = 0
            if "leave 15 minutes" in note:
                buffer = 15

            for event in person_day.get("events", []):
                if event.get("show_as") == "busy":
                    s = parse_time(event.get("start", "00:00")) + delta - buffer
                    e = parse_time(event.get("end", "00:00")) + delta + buffer
                    if e > s:
                        busy.append([s, e])

        if common_end <= common_start:
            continue

        merged = merge(busy)
        free = []
        current = common_start
        for s, e in merged:
            if e <= common_start:
                continue
            if s >= common_end:
                break
            if s > current:
                free.append([current, s])
            if e > current:
                current = e
        if current < common_end:
            free.append([current, common_end])

        day_starts = []
        for s, e in free:
            if s < common_start:
                s = common_start
            if e > common_end:
                e = common_end
            if e - s < minutes:
                continue

            first = s
            if earliest_minutes != -1 and first < earliest_minutes:
                first = earliest_minutes
            first = ceil_quarter(first)
            last = e - minutes
            if latest_minutes != -1:
                cap = latest_minutes - minutes
                if cap < last:
                    last = cap

            t = first
            while t <= last:
                if t + minutes <= e:
                    day_starts.append(format_time(t))
                t += 15

        if day_starts:
            starts[day_key] = day_starts

    return {"starts": starts}
